/**
 * Event ids: ULIDs, generated by the sender (rich-messaging-plan.md §4.2).
 *
 * A ULID is a 48-bit millisecond timestamp and 80 random bits, in Crockford
 * base32. Ids from one sender sort in the order they were made, which is how
 * a receiver orders that sender's events ("change, then remove" resolves
 * correctly however pickup batches arrive). Within one millisecond the
 * random part is incremented, so ids stay strictly increasing.
 *
 * @module chat/eventId
 */

const CROCKFORD = '0123456789ABCDEFGHJKMNPQRSTVWXYZ'
const TIME_LENGTH = 10
const RANDOM_LENGTH = 16

export type RandomSource = (bytes: Uint8Array) => Uint8Array

const defaultRandom: RandomSource = (bytes) => {
  const cryptoObject = (globalThis as { crypto?: { getRandomValues?: (b: Uint8Array) => Uint8Array } }).crypto
  if (!cryptoObject?.getRandomValues) throw new Error('chat eventId: no crypto.getRandomValues available')
  return cryptoObject.getRandomValues(bytes)
}

function encodeTime(ms: number): string {
  let value = ms
  let out = ''
  for (let i = 0; i < TIME_LENGTH; i++) {
    out = CROCKFORD[value % 32] + out
    value = Math.floor(value / 32)
  }
  return out
}

/** 80 random bits as 16 base32 digits (each digit holds 5 bits). */
function randomDigits(random: RandomSource): number[] {
  const bytes = random(new Uint8Array(RANDOM_LENGTH))
  return Array.from(bytes, (byte) => byte % 32)
}

/** Add one to a base32 digit array; false if it overflowed. */
function increment(digits: number[]): boolean {
  for (let i = digits.length - 1; i >= 0; i--) {
    if (digits[i] < 31) {
      digits[i] += 1
      return true
    }
    digits[i] = 0
  }
  return false
}

/** A generator of strictly increasing ULIDs. */
export function createEventIdFactory(options: { now?: () => number; random?: RandomSource } = {}) {
  const now = options.now ?? Date.now
  const random = options.random ?? defaultRandom
  let lastTime = -1
  let lastDigits: number[] = []

  return function newEventId(): string {
    let time = now()
    if (time <= lastTime) {
      // Same (or an earlier) millisecond: keep the last time and step the random part.
      time = lastTime
      if (!increment(lastDigits)) {
        time = lastTime + 1
        lastDigits = randomDigits(random)
      }
    } else {
      lastDigits = randomDigits(random)
    }
    lastTime = time
    return encodeTime(time) + lastDigits.map((d) => CROCKFORD[d]).join('')
  }
}

/** The app-wide generator. */
export const newEventId = createEventIdFactory()

/**
 * The time a ULID claims, in epoch ms: its first 10 characters, Crockford base32. The sender chooses it, so it is a
 * claim, not a fact; parseChatEvent bounds it where it decides an outcome shared by both phones (a chat's timer).
 * The layout read here is the ULID spec's (github.com/ulid/spec, which carries no version number; its text as of
 * October 2026: a 48-bit millisecond time, most significant first, in the first 10 characters), and it is the one
 * createEventIdFactory above writes. Ids that stopped following it would decode to a wrong time with no error, so
 * re-check this if the event id format (plan D3) ever changes.
 *
 * Callers must have validated the id with isUlid, or handle NaN themselves: a character outside Crockford base32 gives
 * NaN, and NaN compares false both ways, so a bound written as `decodeUlidTime(id) > limit` would let it through.
 * parseChatEvent checks isUlid before every type branch, so its future-event bound never sees NaN.
 */
export function decodeUlidTime(id: string): number {
  let ms = 0
  for (const ch of id.slice(0, TIME_LENGTH).toUpperCase()) {
    const digit = CROCKFORD.indexOf(ch)
    if (digit < 0) return NaN
    ms = ms * 32 + digit
  }
  return ms
}
